-- +goose Up
CREATE TABLE IF NOT EXISTS public.analytics_events (
    id uuid NOT NULL,
    event_type text NOT NULL,
    user_id uuid,
    job_id uuid,
    is_guest boolean DEFAULT false,
    tool_type text,
    plan_name text,
    file_size bigint DEFAULT 0,
    metadata jsonb,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    persisted_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS public.api_metric_samples (
    id uuid NOT NULL,
    sampled_at timestamp with time zone NOT NULL,
    requests bigint DEFAULT 0,
    client_errors bigint DEFAULT 0,
    server_errors bigint DEFAULT 0,
    timeouts bigint DEFAULT 0,
    avg_ms numeric DEFAULT 0,
    p50_ms numeric DEFAULT 0,
    p95_ms numeric DEFAULT 0,
    p99_ms numeric DEFAULT 0,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS public.daily_metrics (
    id uuid NOT NULL,
    date date NOT NULL,
    metric_name text NOT NULL,
    metric_value numeric NOT NULL,
    dimensions jsonb,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP
);

-- +goose StatementBegin
DO $$ BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint
                   WHERE conname = 'analytics_events_pkey'
                     AND conrelid = 'public.analytics_events'::regclass) THEN
        ALTER TABLE ONLY public.analytics_events
            ADD CONSTRAINT analytics_events_pkey PRIMARY KEY (id);
    END IF;
EXCEPTION WHEN duplicate_object OR duplicate_table OR invalid_table_definition THEN NULL;
END $$;
-- +goose StatementEnd

