CREATE INDEX IF NOT EXISTS idx_api_sample_time ON public.api_metric_samples USING btree (sampled_at);

CREATE UNIQUE INDEX IF NOT EXISTS idx_daily_metric ON public.daily_metrics USING btree (date, metric_name);

CREATE INDEX IF NOT EXISTS idx_event_created ON public.analytics_events USING btree (created_at);

CREATE INDEX IF NOT EXISTS idx_event_created_user ON public.analytics_events USING btree (created_at, user_id) WHERE ((user_id IS NOT NULL) AND (is_guest = false));

CREATE INDEX IF NOT EXISTS idx_event_job_type ON public.analytics_events USING btree (job_id, event_type) WHERE (job_id IS NOT NULL);

CREATE INDEX IF NOT EXISTS idx_event_tool_created ON public.analytics_events USING btree (tool_type, created_at);

CREATE INDEX IF NOT EXISTS idx_event_type_created ON public.analytics_events USING btree (event_type, created_at);

CREATE INDEX IF NOT EXISTS idx_event_user_created ON public.analytics_events USING btree (user_id, created_at);

CREATE INDEX IF NOT EXISTS idx_event_user_type_created ON public.analytics_events USING btree (user_id, event_type, created_at);

